def filter_nulls(data):
    return [item for item in data if item is not None]

def normalize_strings(data):
    return [item.strip().lower() if isinstance(item, str) else item for item in data]

def deduplicate(data):
    seen = set()
    return [item for item in data if not (item in seen or seen.add(item))]

def sort_pipeline(data):
    return sorted(data)

class Pipeline:
    def __init__(self, data):
        self.data = data

    def run(self):
        return pipe(
            filter_nulls,
            normalize_strings,
            deduplicate,
            sort_pipeline
        )(self.data)

def pipe(*transforms):
    def runner(data):
        result = data
        for transform in transforms:
            result = transform(result)
        return result
    return runner
